"""Human-reviewed answer-illustration specifications for all 204 questions in chapters 3–10."""
from pathlib import Path
import json,csv,html,collections,re
R=Path(__file__).resolve().parents[1];C=R/'app/src/main/assets/content'
Q={q['canonicalId']:q for c in range(3,11)for q in json.loads((C/f'chapter{c}.json').read_text())}
ART=json.loads((R/'qa/source/owner-art-2026-10-21.json').read_text())['scientific']
S={}
def add(c,n,spec,priority='بالا',reuse=()):
 cid=f'g7_ch{c:02}_{n if isinstance(n,str) else "q"+str(n).zfill(2)}';assert cid in Q
 S[cid]=dict(spec=spec,priority=priority,reuseOf=None)
 for other in reuse:
  key=f'g7_ch{c:02}_{other if isinstance(other,str) else "q"+str(other).zfill(2)}';assert key in Q
  S[key]=dict(spec='استفاده از تصویر پاسخ '+cid+' برای بخش مفهومیِ مشترک؛ پاسخ متنی کامل همین سؤال حفظ شود و شمارهٔ گزینه یا پاسخ سؤال دیگر روی آن نیاید.',priority='استفادهٔ مشترک',reuseOf=cid)
# Numbers, atom counts, source labels, and arrow directions are deliberate.
add(3,5,'پارچ سرد با آب و یخ درون آن؛ پیکان بخار آبِ هوای بیرون به سطح پارچ و قطره‌های روی سطح بیرونی. قطره‌ها از داخل دیواره عبور نکنند.')
add(3,10,'سه مدل متان، کربن‌دی‌اکسید و آب با راهنمای رنگ ثابت C، O و H؛ شمار اتم‌ها به‌ترتیب CH4، CO2 و H2O باشد. فرمول‌ها چپ‌به‌راست و نام‌های فارسی جدا باشند.')
add(3,12,'سه تصویر ارسالی کنار هم، با ترتیب اصلی راست به چپ: عنصر نافلز، عنصر فلز، ترکیب. نام هر گروه زیر همان شکل و توضیح کوتاه یک‌نوع یا چندنوع اتم؛ رنگ‌ها و پیوندهای منبع حفظ شوند.',reuse=(14,))
add(3,15,'نسخهٔ پاسخ‌دار همان نقشهٔ کامل ارسالی، برای مدل‌های همین سؤال: هر مولکول ۲ اتم اکسیژن و ۱ اتم کربن؛ در هر اتم اکسیژن ۸ الکترون، ۸ پروتون و ۸ نوترون؛ در هر اتم کربن ۶، ۶ و ۶. راهنمای رنگ و شاخه‌بندی عین شکل؛ فقط خانه‌های نسخهٔ پاسخ پُر شوند.')
add(3,17,'مدل اتم با هستهٔ مشخص، پروتون و نوترون داخل هسته و الکترون بیرون آن؛ نشانه‌های e، p و n و برابری تعداد الکترون و پروتون در اتم خنثی. اندازهٔ ذرات صرفاً شماتیک باشد.',reuse=(16,'mcq05'))
add(3,18,'مقایسهٔ سه نمونه با جرم برابرِ ۵ گرم: شکر، آب و هوا. ترازوی توپ پیش و پس از افزودن ۵ گرم هوا جدا نشان داده شود. نسبت حجم‌ها شماتیک است؛ حجم عددی یا اندازهٔ واقعیِ حدسی داده نشود.','تکمیلی')
add(3,19,'سه سرنگ با نوک بسته، محتوی شن، آب و هوا؛ وضعیت پیش و پس از فشار با پیکان یکسان. کاهش محسوس حجم در سرنگ هوا و کاهش ناچیز در دو مورد دیگر؛ مایع کاملاً بدون تراکم معرفی نشود.',reuse=(20,'mcq07'))
add(3,21,'همان نمودار منبع، با برچسب پاسخ ستون‌ها از راست به چپ: آب، شیشه، اکسیژن، مس. ارتفاع ستون‌ها و ترتیب‌شان عوض نشود؛ جمع‌بندی گاز، مایع، جامد فلزی و جامد نافلزی جدا باشد.')
add(3,22,'دو پنل آب داغ و مخلوط آب و یخ؛ هوای داخل بطری و بادکنک در حالت گرم منبسط و در حالت سرد منقبض شود. پیکان‌های ورود و خروج هوا مشخص؛ عبارت مبهم «برعکس» استفاده نشود.')
add(3,24,'سه آرایشِ ذرات آب مطابق شماره‌های منبع، با تأکید بر شکل ۳ برای بخار و فاصلهٔ بیشتر مولکول‌ها. خود مولکول H2O بزرگ‌تر نشود و فاصلهٔ بین مولکول‌ها تغییر کند.')
add(4,4,'مقطع سیم با مغزی مسی و روکش پلاستیکی؛ یک راهنمای رسانا و نارسانا و مسیر جریان در مغزی. روکش حامل جریان نمایش داده نشود.','تکمیلی')
add(4,8,'استفاده از شکل ارسالیِ لغزش لایه‌های اتم‌های فلز: قبل از ضربه و پس از ضربه، پیکان نیرو و جابه‌جایی لایه‌ها. اتم‌ها نشکنند و تعداد آن‌ها کم نشود.',reuse=('mcq03',))
add(4,10,'نمودار چگالی منبع با تأکید روی چوب و شیشه و یک پنل کوچکِ شناوری: چوب بالای آب و شیشه پایین آب. واحد و ارتفاع همهٔ ستون‌ها از اصل نمودار حفظ شوند.')
add(4,11,'همان ظرف چهارلایه با حروف A تا D و پاسخ کنار هر حرف: چوب‌پنبه، آب، آلیاژ برنج، جیوه. ترتیب چگالی از کم به زیاد در یک سطر مستقل و چپ‌به‌راست یا عمودی خوانا باشد.')
add(4,16,'مدل شماتیک فلز خالص و آلیاژ با راهنمای اتم‌ها؛ ذوب، مخلوط‌کردن و انجماد در سه مرحله. نمونهٔ فولاد زنگ‌نزن با آهن، کروم و نیکل؛ هیچ درصد ترکیبیِ تازه درج نشود.','تکمیلی')
add(4,'mcq04','همان پنج ستون A تا E بدون تغییر ارتفاع؛ ستون‌های پاسخ فولادی و مسی مطابق گزینهٔ «الف» یعنی A و B نشانه‌گذاری شوند. نام‌ها جایگزین حروف اصلی نشوند.')
add(5,3,'دو محلول آهن(III)کلرید و سدیم‌هیدروکسید در لوله‌های جدا، افزودن قطره‌قطره و تشکیل رسوب قرمز آجری در لولهٔ آهن. فقط نام مواد و ترتیب همان پاسخنامه؛ عدد یا غلظت تازه داده نشود.')
add(5,4,'نمودار چهارمرحله‌ای شناسایی و برداشت معدن، خالص‌سازی سنگ معدن، گرم‌کردن با کربن و سنگ‌آهک، تولید ورقهٔ آهن. جهت پیکان‌ها یکدست و مواد ورودی کوره کنار آن باشند.',reuse=(5,'mcq05'))
add(5,6,'آزمایش کبریت آغشته به سدیم‌کربنات و آهن(III)اکسید، گرم‌کردن تا نیمه، گذشت ۳۰ ثانیه، پودر روی شیشهٔ ساعتی و حرکت ذرات با آهن‌ربای زیر شیشه. مراحل پاسخنامه جابه‌جا نشوند.')
add(5,11,'نمودار ستونی واقعی تولید سیمان: ۱۳۸۳=۳۳۰۰۰، ۱۳۸۹=۶۱۰۰۰، ۱۳۹۲=۶۸۰۰۰، ۱۳۹۴=۵۸۰۰۰، ۱۳۹۶=۷۰۰۰۰؛ محور عمودی با واحد خود جدول و فاصله‌های مساوی؛ کاهش سال ۱۳۹۴ برجسته شود.')
add(5,13,'سه قاب تهیهٔ گِل کوزه‌گری، شکل‌دادن به خمیر و پختن/لعاب‌دادن؛ پیکان یکدست و زیرنویس کوتاه برای هر مرحله.','تکمیلی')
add(5,14,'ماسه و مواد افزودنی، گرم‌کردن و خمیر شیشه؛ سپس دو شاخهٔ جدا برای قالب‌گیری و دمیدن هوا. مرحلهٔ ذوب با شیشهٔ سرد اشتباه نشود.','تکمیلی')
add(5,15,'همان نمودار ارسالی اندوخته‌ها، بدون تغییر عددها یا ترتیب ستون‌ها؛ طلا به‌عنوان زودترین و کروم به‌عنوان دیرترین مشخص شود. دو نماد جدا برای بازیافت و کاهش مصرف؛ این زمان‌ها پیش‌بینی کتاب‌اند نه آمار روز.')
add(5,16,'سه پنل مقایسه‌ای کاهش مصرف، مصرف دوباره و بازیافت با مثال‌های همین فصل؛ زنبیل پارچه‌ای، استفادهٔ دوباره از شیشه و ذوب ظروف فلزی. این سه مفهوم در یک چرخهٔ واحد ادغام نشوند.','تکمیلی',reuse=('mcq01','mcq03'))
add(5,17,'شکل چرخهٔ فلز ارسالی با برچسب‌های ظروف فرسوده، ذوب، شمش و ساخت ظرف نو. پیکان برگشت به مصرف روشن و سر پیکان‌ها حفظ شود.',reuse=('mcq02',))
add(6,3,'نمودار بارش همان شهرهای کتاب با همهٔ نام‌ها و مقیاس اصلی؛ ستونِ پاسخِ سؤال برجسته شود. علت‌های تفاوت بارش در کادر جدا و بدون تغییر دادهٔ نمودار بیایند.','تکمیلی')
add(6,5,'بشر آب گرم، نایلون و یخ روی آن؛ تبخیر آب، سردشدن بخار زیر نایلون و تشکیل/سقوط قطره‌ها با پیکان. یخ از داخل پوشش به بشر نریزد.')
add(6,6,'همان دو نمودار دایره‌ای ارسالی: ۹۷٪ آب شور، ۳٪ آب شیرین؛ شاخهٔ آب شیرین با یخچال‌ها، آب زیرزمینی و رود/دریاچه. برای زیربخش‌ها درصدِ تازه ساخته نشود.',reuse=(4,))
add(6,7,'سه پنل تشکیل باران، برف و تگرگ؛ قطرهٔ مایع، بلور یخ و لایه‌های تگرگ قابل تشخیص باشند. گردش بالاروندهٔ تگرگ نشان داده شود؛ برف و تگرگ یک فرایند واحد نباشند.')
add(6,9,'مدل ظرف خاک ماسه/رس با بارش روی سطح، رواناب، نفوذ و تبخیر؛ مسیر هر کدام جدا باشد. برای بخش چرخهٔ کامل از تصویر پاسخ فصل ۷ سؤال ۲۸ استفاده شود.',reuse=(10,))
add(6,11,'مقطع رود با سنگ سخت روی سنگ نرم، فرسایش بیشتر لایهٔ نرم و پرتگاه آبشار. جهت جریان و تفاوت مقاومت دو لایه مشخص باشد.')
add(6,16,'دو ساحل A و B با همان نسبت سختی سنگ‌های کتاب؛ کنار هر مقطع، اثر فرسایش و شکل ساحل توضیح داده شود. برچسب‌های A/B و نتیجهٔ پاسخنامه حفظ شوند.','تکمیلی')
add(6,19,'مقطع دریا، جابه‌جایی ناگهانی بستر، انتقال موج و افزایش ارتفاع آن نزدیک ساحل. سونامی به باد نسبت داده نشود و مقدار سرعت/ارتفاع تازه درج نشود.')
add(6,20,'دو وضعیت جزر و مد با سطح آب کم و زیاد، موقعیت شماتیک ماه و زمین و نقش جاذبه. مقیاس فاصله‌ها واقعی معرفی نشود؛ کاربردها در کادر جدا قرار گیرند.')
add(6,21,'دو پنل یخچال قطبی و کوهستانی؛ انباشته‌شدن و فشرده‌شدن برف و جهت حرکت یخ. یخچال طبیعی با تودهٔ یخ شناور اشتباه نشود.','تکمیلی')
add(7,4,'دو دامنهٔ منبع، یکی با پوشش گیاهی بیشتر؛ پیکان نفوذ و رواناب قابل مقایسه و طول پیکان‌ها صرفاً شماتیک باشد.')
add(7,5,'چهار بطری شماره‌دار ارسالی با نام دقیق خاک هر بطری و آب جمع‌شده در ظرف پایین. مقایسهٔ ماسه، رس و مخلوط‌ها طبق پاسخنامه؛ مقدار آب ورودی و زمان مقایسه یکسان نمایش داده شود.')
add(7,10,'مقطع آهک با نفوذ آب و انحلال تدریجی درزها تا تشکیل غار. انحلال با ذوب حرارتی یا کندن مکانیکی اشتباه نشود.','تکمیلی')
add(7,11,'بشر ماسه و استوانهٔ مدرج پیش و پس از ریختن آب؛ آبِ وارد فضاهای خالی با رنگ جدا. رابطهٔ حجم فضای خالی و حجم آب مصرف‌شده بدون عددِ ساختگی.')
add(7,13,'چینش ذرات همان شکل‌های کتاب و مسیرهای مرتبط فضای خالی؛ مقایسهٔ نفوذپذیری و جنس خاک. عدد تازه‌ای برای درصد تخلخل داده نشود.')
add(7,14,'نسخهٔ پاسخ‌دار شکل ارسالی آبخوان: ۱ منطقهٔ بالای اشباع، ۲ سطح ایستابی، ۳ منطقهٔ اشباع. قسمت ب نیز با نمایش پُرشدن همهٔ فضاهای خالیِ منطقهٔ اشباع توضیح داده شود.',reuse=(9,27))
add(7,15,'ظرف شفاف، لایهٔ ماسه، آب پایین و بخش بالایی بدون اشباع؛ مرز سطح ایستابی مشخص. آبخوان به معنی یک غار بزرگ پُر از آب نمایش داده نشود.')
add(7,16,'دو مقطع هم‌مقیاس گیلان و یزد با خط سطح زمین و سطح ایستابی؛ عمق چاه تا برخورد با آب مشخص، بدون متر یا عمق حدسی.',reuse=('mcq03',))
add(7,19,'مقطع آبخوان آزاد با یک لایهٔ نفوذپذیر روی لایهٔ نفوذناپذیر، سطح ایستابی و چاه/قنات. آزاد بودن سطح بالا و هفت پاسخ مستقل این سؤال روشن باشد.')
add(7,20,'مقطع آبخوان تحت فشار با لایهٔ نفوذپذیر بین دو لایهٔ نفوذناپذیر و تغذیه در ناحیهٔ شیب‌دار. لایه‌بندی و فشار با آبخوان آزاد مخلوط نشود.')
add(7,21,'برخورد آب زیرزمینی با دامنه و خروج طبیعی آب در سطح به صورت چشمه؛ مسیر آب و سطح لایهٔ نفوذناپذیر مشخص باشد.','تکمیلی')
add(7,23,'شکل ارسالی برداشت بی‌رویه با دو سطح ایستابی قبل/بعد و عمق بیشتر چاه؛ پیکان افت سطح، خشک‌شدن چاه کم‌عمق و نشست زمین در پنل جدا. دهانهٔ چاه بالای سطح زمین حفظ شود.')
add(7,25,'مسیر نفوذ فاضلاب از سطح به آبخوان با پیکان رنگی و محل چاه آب. آلودگی به شکل عبور مستقیم از لایهٔ نفوذناپذیر رسم نشود.','تکمیلی')
add(7,28,'چرخهٔ آب با خورشید، تبخیر، تراکم، بارش، رواناب، نفوذ و برگشت آب زیرزمینی. جهت همهٔ پیکان‌ها درست و آبی که از خشکی خارج می‌شود به دریا متصل باشد.')
add(7,'mcq05','استوانهٔ مدرج و بشر ماسه با عددهای خود سؤال: ۵۰ و ۲۰ سی‌سی ریخته‌شده، ۸ سی‌سی باقی‌مانده؛ محاسبهٔ 50 + 20 − 8 = 62 در سطر مستقل و واحد سانتی‌متر مکعب.','تکمیلی')
add(7,'mcq06','نسخهٔ راهنمادار همان مقطع قنات ارسالی: مادرچاه، میله‌ها، کورهٔ زیرزمینی و مظهر قنات. مسیر آب از مادرچاه به خروجی و شیب ملایم کوره حفظ شود.')
add(8,2,'دو آزمایش مستقل وابستگی کار به نیرو و جابه‌جایی، با نیروسنج و تخته؛ ۳۰ و ۵۰ سانتی‌مترِ متن در مرحلهٔ اول و تغییر تعداد تخته‌ها در مرحلهٔ دوم. فقط یک عامل در هر مقایسه عوض شود.')
add(8,3,'شش حالت تصویر ارسالی با شماره‌های اصلی: ۱ شروع حرکت، ۲ تندشدن، ۳ کندشدن، ۴ توقف، ۵ تغییر شکل، ۶ تغییر جهت. نوشته‌ها زیر همان شماره قرار گیرند.')
add(8,4,'سه حالت ارسالی با پیکان نیروی دست و جابه‌جایی؛ در حالت ۳، عمودبودن نیرو بر جابه‌جایی و صفر بودن کارِ همان نیرو مشخص شود. صفر بودن کل انرژی مصرفی فرد نتیجه‌گیری نشود.')
add(8,7,'دو پنل سطح شیب‌دار و بلندکردن مستقیم با عددهای ۸۰ نیوتون/۳ متر و ۲۴۰ نیوتون/۱ متر؛ هر دو کار ۲۴۰ ژول. پیکان نیرو و مسیر حرکت جدا و ارتفاع ۱ متر حفظ شود.')
add(8,8,'زنجیرهٔ باتری با انرژی شیمیایی به انرژی الکتریکی، سپس دو خروجی نورانی و گرمایی لامپ. شاخهٔ گرمایی حذف نشود و جهت خواندن همهٔ پیکان‌ها یکدست باشد.')
add(8,10,'دو مقایسهٔ مجزا: فرشاد ۳۲ و احسان ۲۸ کیلوگرم با سرعت برابر؛ فاطمه و رها با جرم برابر ۴۱ کیلوگرم و سرعت متفاوت. عامل ثابت و عامل متفاوت مشخص، سرعت عددی حدسی داده نشود.','تکمیلی',reuse=(9,))
add(8,12,'سه شاخهٔ پتانسیل گرانشی، شیمیایی و کشسانی؛ نمونه‌های آب پشت سد، غذا/سوخت، فنر یا کش. عبارت‌ها و مثال‌های هر شاخه با پاسخ جدول بومی یکی باشند.')
add(8,13,'دو آزمایش مجزا: گلولهٔ سبک و سنگین از ارتفاع یکسان ۱ متر؛ سپس یک گلوله از ۰٫۵ و ۱ متر. اثر وزن و ارتفاع جدا، بدون نتیجه‌گیری از چند عامل هم‌زمان.',reuse=(11,15))
add(8,14,'کمان کشیده و تیر رهاشده با تبدیل پتانسیل کشسانی کمان به انرژی جنبشی تیر؛ پیکان انتقال انرژی و جهت حرکت تیر جدا باشند.','تکمیلی')
add(8,17,'نمودار جریان انرژی خودرو با ورودی ۱۶۰۰ ژول، خروجی مفید ۵۰۰ ژول و خروجی دیگر ۱۱۰۰ ژول. رابطهٔ 1600 − 500 = 1100 جدا و راستای علمی چپ‌به‌راست باشد؛ انرژی با نیرو اشتباه نشود.')
add(8,19,'شکل ارسالی خورشید، گیاه/محصول کشاورزی، غذا و انسان در حال کار؛ نام مراحل و جهت پیکان‌ها حفظ شود. خورشید منبع زنجیره است و انرژی در غذا به صورت شیمیایی ذخیره می‌شود.')
add(8,'mcq07','همان مسیر توپ با حروف A تا D؛ بالاترین نقطه A و بیشینهٔ انرژی پتانسیل گرانشی مشخص شود. افت نهایی و تبدیل بخشی از انرژی به گرما توضیح کوتاه داشته باشد.','تکمیلی')
add(9,4,'دو مسیر مجزای شکل ارسالی برای زغال‌سنگ و نفت/گاز: گیاهان خشکی و جانداران ریز دریایی، دفن، فشار/گرما و گذشت زمان طولانی. این دو ماده از یک مسیر یکسان ساخته نشوند.')
add(9,8,'صفحهٔ خورشیدی با تبدیل نورانی به الکتریکی و نمایش سهم تقریبی ۲۰٪ مطابق متن؛ کاربردهای کتاب در قاب‌های کوچک. پنل فتوولتاییک با آبگرم‌کن خورشیدی یکسان رسم نشود.','تکمیلی')
add(9,9,'آبگرم‌کن خورشیدی با لولهٔ تیره، تابش خورشید، آب ورودی و خروجی گرم؛ بازهٔ ۶۰ تا ۷۰ درجه فقط طبق متن پاسخنامه. مسیر گرما و مسیر گردش آب قابل تفکیک باشند.')
add(9,10,'توربین بادی با پیکان باد، محور توربین، مولد و خروجی برق؛ زنجیرهٔ انرژی جنبشی باد به الکتریکی. تصویر توربین پاسخ نام دستگاه را فقط در نسخهٔ پاسخ آشکار کند.')
add(9,11,'همان زنجیرهٔ خورشید، گرم‌شدن نابرابر زمین، جریان باد، توربین و برق. در پنل گردش هوا، هوای گرم بالا و هوای خنک پایین حرکت کند؛ جهت پیکان‌های سطح و ارتفاع معکوس باشند.')
add(9,12,'زنجیرهٔ خورشید، باد، موج‌های دریا و تولید برق؛ باد به عنوان حلقهٔ تشکیل موج مشخص باشد. تصویر ارسالیِ سؤال پایه است و نباید خورشید مستقیماً جای باد را بگیرد.')
add(9,13,'شکل زمین‌گرمایی ارسالی با سنگ‌های داغ، چاه‌ها/مسیر سیال و خروجی برق؛ نشانه‌های منبع حفظ شوند. چشمهٔ آب گرم، گرمایش و تولید برق در قاب کاربردها.','تکمیلی')
add(9,14,'تفاله/باقی‌ماندهٔ محصولات کشاورزی، مخزن در شرایط بی‌هوازی، خروج زیست‌گاز و مصرف خانگی/صنعتی. نبود هوا واضح باشد؛ پنل کوچک اتانول از تفالهٔ نیشکر جدا از مخزن زیست‌گاز.',reuse=('mcq01','mcq03'))
add(9,15,'همان سد ارسالی با مسیر آب، توربین و مولد: در این شکل ۱=مولد و ۲=توربین. تبدیل پتانسیل گرانشی آب به حرکت توربین و سپس الکتریکی. کلید چاپیِ جابه‌جا به‌عنوان نسخهٔ صحیح تصویر بازتولید نشود.')
add(10,2,'سه مرحلهٔ درجه‌بندی دماسنج: تعادل با مخلوط آب و یخ در ۰، مجاورت بخار آب جوشان در ۱۰۰ و تقسیم فاصله به ۱۰۰ قسمت مساوی؛ شرایط استاندارد ذکر شود.')
add(10,5,'دو جسم A و B با همان دماهای شکل کتاب؛ جهت گرما از B گرم‌تر به A سردتر و توقف انتقال خالص هنگام برابری دما. اعداد دما از منبع عیناً نقل شوند و دمای تعادل حدس زده نشود.',)
add(10,8,'زنجیرهٔ ذرات جامد و انتقال انرژی از سر گرم به سر سرد؛ ذرات در جای خود نوسان کنند و جریان توده‌ای ماده مانند همرفت نشان داده نشود.',)
add(10,9,'سه میلهٔ مسی، آلومینیمی و آهنی با طول/ضخامت و شرایط گرمایش یکسان و کبریت متصل با پارافین؛ افتادن به ترتیب مس، آلومینیم، آهن. پیکان رسانش و گرم‌شدن سر میله‌ها.')
add(10,12,'مقطع پشم‌شیشه/پر با رشته‌ها و هوای محبوس بین آن‌ها؛ مسیر دشوار انتقال گرما. عایق بودن صرفاً به جنس شیشه نسبت داده نشود.','تکمیلی')
add(10,13,'همان شکل پاسخِ مسیر جوهر که در برنامه از پاسخنامه جدا شده است: شعله زیر یک سمت، صعود نزدیک شعله، حرکت در بالا، نزول سمت مقابل و بازگشت در پایین. هیچ پیکانی برخلاف این گردش نباشد.')
add(10,14,'شکل ارسالی ظرف آب با منبع گرما زیر مرکز؛ صعود آب گرم وسط، حرکت در سطح، نزول آب خنک‌تر کنار دیواره و برگشت پایین. هر دو حلقه در جهت‌های مکمل باشند.')
add(10,15,'مقطع اتاق، بخاری/رادیاتور یک‌طرف، صعود هوای گرم کنار آن و برگشت هوای سرد در کف؛ ارتفاع پیکان‌ها و محل منبع گرما واضح باشد.')
add(10,16,'دو پنل ارسالی روز و شب: روز بادِ سطحی از دریا به خشکی، شب از خشکی به دریا؛ مسیر بالا در هر پنل برعکس مسیر سطح. محل دریا، خشکی، خورشید و ماه ثابت و مشخص باشد.')
add(10,18,'دو ورقهٔ براق و سیاه مقابل همان بخاری تابشی، موم و چوب‌پنبه در پشت هر ورقه؛ افتادن زودتر چوب‌پنبهٔ ورقهٔ سیاه و بازتاب بیشتر ورقهٔ براق. آزمایش جذب با آزمایش گسیل یکسان معرفی نشود.',reuse=(17,))
add(10,19,'دو قوطی یکسان با آب داغِ هم‌جرم و هم‌دما؛ سطح سیاه و سفید و دو دماسنج. منحنی ۱ برای سیاه و ۲ برای سفید طبق شکل کتاب؛ همهٔ عوامل دیگر یکسان باشند.',reuse=('mcq04',))
add(10,21,'فقط نمودار و کاربردهای معتبر با یادداشت مغایرت: از رنگ مرئی چای به‌تنهایی سرعت سردشدن تعیین نشود؛ دربارهٔ خرس قطبی، استتارِ پوشش سفید از عایق‌بودن مو/چربی جدا شود. تصویر نادرستِ اتلاف کمتر گرما صرفاً به علت سفیدبودن مو ساخته نشود.','تکمیلی')
add(10,23,'مقطع خانه با عایق سقف/دیوار، پنجرهٔ مناسب و درزگیری درها طبق پاسخنامه؛ محل‌های اتلاف و راه کاهش آن‌ها مشخص، بدون درصد اتلاف حدسی.','تکمیلی')
add(10,24,'مقطع همان فلاسک ارسالی با درپوش عایق، دو جداره، خلأ و سطوح نقره‌اندود؛ کاهش رسانش/همرفت در فاصلهٔ جداره‌ها و کاهش تابش با سطح نقره‌ای. عایق کامل یا تابش صفر ادعا نشود.')
add(10,25,'سه پنل رسانش، همرفت و تابش؛ دو مسیر اول نیازمند ماده و تابش قادر به عبور از خلأ. موج تابشی با جریان هوا اشتباه نشود.','تکمیلی',reuse=('mcq03',))
add(10,'mcq02','همان نمودار زمان/دما با دو خط ۱ و ۲ و برچسب درست محور‌ها؛ فقط سرعت افزایش دمای مشاهده‌شده مقایسه شود. از این نمودار به‌تنهایی علت قطعی یا برابر بودن ظرفیت گرمایی نتیجه‌گیری نشود.','تکمیلی')

add(3,11,'نقشهٔ دوشاخهٔ ذرات سازنده: گروه اتمی با نقره، آلومینیم، آهن، مس، جیوه و طلا؛ گروه مولکولی با کربن‌دی‌اکسید، کلر، گوگرد، آب، متان، اکسیژن و نیتروژن. نام همهٔ مواد و راهنمای نمونهٔ اتم/مولکول حفظ شود.','تکمیلی')
add(3,'mcq04','سه پنل جیوهٔ مایع، مولکول آب سه‌اتمی و مولکول هشت‌اتمی گوگرد؛ سه عبارت درستِ گزینه‌ها نشان داده شوند. تصاویر متان و کربن‌دی‌اکسید جایگزین گوگرد و جیوه نشوند.','تکمیلی')
add(8,'mcq05','همان دو خودروی مشابه با شماره‌های ۱ و ۲؛ پیکان سرعت خودروی ۱ بیشتر و انرژی جنبشی آن بیشتر باشد. جرم ثابت است و عدد تازه‌ای برای سرعت درج نشود.','تکمیلی')
add(8,'mcq06','خودرو و کامیونِ شکل منبع با پیکان‌های سرعت برابر؛ جرم بیشتر کامیون و انرژی جنبشی بیشتر آن مشخص باشد. از تصویر مقایسهٔ دو انسان با جرم‌های متفاوت استفاده نشود.','تکمیلی')
add(10,4,'میخ داغ داخل آب سردتر، با پیکان انتقال گرما از میخ به آب و دو وضعیت قبل/بعد تا رسیدن به تعادل؛ شش جای خالی در متن بومی می‌مانند. دما یا ظرفیت گرماییِ عددی تازه ساخته نشود.')
add(10,10,'سیخ فلزی و مسیر رسانش گرما از سمت داغ به دست؛ در پنل دوم دستگیره یا پوشش عایق مطابق پاسخنامه. پیکان رسانش با جریان هوا اشتباه نشود.','تکمیلی')
add(10,20,'دو مقایسهٔ مستقلِ عوامل تابش: اجسام هم‌جنس و هم‌دما با سطح‌های مورد بررسی کتاب، و یک جسم با دماهای متفاوت. دما و ویژگی سطح هم‌زمان تغییر نکنند؛ شدت تابش صرفاً شماتیک و بدون عدد حدسی.','تکمیلی')

rows=[]
for cid,item in S.items():
 q=Q[cid];base=item['reuseOf']or cid
 supplied=[a for a in ART if a['question']==cid and a['role']=='question']
 figure=[b['asset']for b in q['nativeQuestion']if b['type']=='figure']
 status='استفاده از تصویر مشترک' if item['reuseOf']else ('شکل سؤال موجود است؛ نسخهٔ پاسخ‌دار/توضیح‌دار آماده شود' if supplied or figure else 'تصویر پاسخ تازه لازم است')
 if cid=='g7_ch10_q13':status='شکل پاسخ اصلی در برنامه موجود است؛ نیاز به ساخت تازه ندارد'
 rows.append(dict(id=cid,chapter=q['relatedChapter'],kind='چهارگزینه‌ای'if q['section']=='چهارگزینه‌ای'else'سؤال',number=q['sourceNumber'],page=q['sourcePage'],title=q['title'],priority=item['priority'],filename=base+'_answer.png',editableFilename=base+'_answer.svg',reuseOf=item['reuseOf'],status=status,baseFiles=[a['sourceFilename']for a in supplied]or figure,spec=item['spec']))
rows.sort(key=lambda x:(x['chapter'],x['kind']=='چهارگزینه‌ای',x['number']))
review=[dict(id=cid,decision='تصویر پاسخ مفید است'if cid in S else'متن/جدول/فرمول بومی کافی است؛ تصویر پاسخ تازه ضروری نیست',suggestedFile=(S[cid]['reuseOf']or cid)+'_answer.png'if cid in S else None)for cid in Q]
result=dict(date='2026-10-21',edition=1405,chapters=list(range(3,11)),questionsReviewed=len(Q),recommendedQuestionUses=len(rows),uniqueSuggestedFiles=len({r['filename']for r in rows}),review=review,rows=rows,
 commonSpecification='فقط شکل پاسخ، نه صورت کامل سؤال. متن فارسی کوتاه و جدا از فرمول‌های چپ‌به‌راست؛ SVG قابل ویرایش و PNG با ضلع بلند دست‌کم ۲۴۰۰ پیکسل، زمینهٔ سفید و حاشیهٔ کافی. برچسب/عدد/رنگ مرجع حفظ شود. پاسخ تصویری فقط پس از باز شدن مجاز پاسخ نمایش داده شود. تصاویر فعلی سؤال، خودبه‌خود پاسخ تصویریِ آماده محسوب نمی‌شوند.')
(R/'review/answer-illustrations-ch3-10.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
fields=['chapter','kind','number','page','title','priority','filename','editableFilename','status','reuseOf','baseFiles','spec']
with (R/'review/Answer_Illustrations_Ch3-10_FA.csv').open('w',encoding='utf-8-sig',newline='')as f:
 w=csv.DictWriter(f,fieldnames=fields,extrasaction='ignore');w.writeheader();w.writerows([{**r,'baseFiles':' | '.join(r['baseFiles'])}for r in rows])
md=['# تصاویر پیشنهادی پاسخ فصل‌های ۳ تا ۱۰','',f'هر {len(Q)} سؤال بررسی شده است. {len(rows)} کاربرد تصویری با {result["uniqueSuggestedFiles"]} فایل متمایز پیشنهاد می‌شود؛ موارد مشترک تصویر تازهٔ جداگانه نمی‌خواهند. این فهرست، مشخصات سفارش تصویر است؛ جز شکل همرفتِ فصل ۱۰ سؤال ۱۳، تصاویر پاسخ این فهرست هنوز ساخته نشده‌اند.','',result['commonSpecification'],'','| فصل/سؤال | صفحه | اولویت | فایل پیشنهادی | وضعیت | مشخصات |','|---|---|---|---|---|---|']
for r in rows:md.append(f'| {r["chapter"]} / {r["kind"]} {r["number"]} | {r["page"]} | {r["priority"]} | `{r["filename"]}` | {r["status"]} | {r["spec"]} |')
(R/'review/Answer_Illustrations_Ch3-10_FA.md').write_text('\n'.join(md)+'\n')
# A standalone, searchable report, readable locally and printable as a PDF.
esc=html.escape

def format_spec(s):
 return re.sub(r'\b[0-9]+(?:[ /+.−×=-]+[0-9]+)+\b|[A-Za-z][A-Za-z0-9_]*',lambda m:'<bdi dir="ltr">'+m[0]+'</bdi>',esc(s))

def base_label(s):
 return 'برش اصلی شکل از کتاب کار، صفحهٔ '+s.split('#')[1].split(',')[0] if s.startswith('pdf:') else s

cards=[]
for r in rows:
 cards.append(f'<article data-ch="{r["chapter"]}" data-priority="{esc(r["priority"])}"><div class="meta">فصل {r["chapter"]} · {r["kind"]} {r["number"]} · صفحه {r["page"]} <span>{esc(r["priority"])}</span></div><h2>{esc(r["title"])}</h2><code>{r["filename"]}</code><p>{format_spec(r["spec"])}</p><div class="status">{esc(r["status"])}</div>'+('<p class="base">شکل پایه: <bdi>'+esc(' | '.join(base_label(v)for v in r['baseFiles']))+'</bdi></p>'if r['baseFiles']else'')+'</article>')
body='''<!doctype html><html lang="fa" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>تصاویر پاسخ علوم‌یار هفتم</title><style>body{margin:0;background:#f1f6fa;color:#12264d;font-family:Tahoma,Arial;line-height:1.9}main{max-width:1100px;margin:auto;padding:30px 20px}h1{font-size:27px}header,article,.controls{background:white;border:1px solid #dae4ec;border-radius:18px;padding:22px;margin-bottom:16px}h2{font-size:20px;margin:7px 0}code{direction:ltr;unicode-bidi:plaintext;display:block;text-align:left;max-width:100%;font-size:14px;color:#076e75;overflow-wrap:anywhere}.base{overflow-wrap:anywhere}.meta,.status,.base{font-size:13px;color:#526782}.meta span{background:#e8f7f2;color:#096d61;padding:4px 10px;border-radius:20px;margin-right:10px}p{margin:9px 0}.controls{position:sticky;top:0;box-shadow:0 4px 12px #1231;display:flex;gap:10px;flex-wrap:wrap}select,input{font:inherit;padding:8px;border:1px solid #c5d4df;border-radius:9px}input{flex:1;min-width:160px}article[hidden]{display:none}.warning{border-right:4px solid #eab73b;padding-right:15px}@media print{.controls{display:none}article{break-inside:avoid}body{background:white}main{padding:0}header,article{box-shadow:none}code{font-size:10pt}}</style><main><header><h1>فهرست تصاویر پاسخ علوم‌یار هفتم</h1>'''
body+=f'<p>فصل‌های ۳ تا ۱۰ · ویرایش ۱۴۰۵ · بازبینی {len(Q)} سؤال · {len(rows)} کاربرد تصویری · {result["uniqueSuggestedFiles"]} فایل متمایز</p><p class="warning">این فایل فهرست سفارش و مشخصات تصویر است. تصاویر سؤالِ ارسالی در برنامه استفاده شده‌اند؛ وجود شکل سؤال به معنی آماده‌بودن نسخهٔ پاسخ‌دار آن نیست. تصویر پاسخ اصلی همرفت، فصل ۱۰ سؤال ۱۳، هم‌اکنون موجود است.</p><p>{esc(result["commonSpecification"])}</p></header>'
body+='<div class="controls"><select id="chapter"><option value="">همهٔ فصل‌ها</option>'+''.join(f'<option value="{c}">فصل {c}</option>'for c in range(3,11))+'</select><select id="priority"><option value="">همهٔ اولویت‌ها</option><option>بالا</option><option>تکمیلی</option><option>استفادهٔ مشترک</option></select><input id="search" placeholder="نام فایل، موضوع یا شماره سؤال"><span id="count"></span></div>'+''.join(cards)+'''</main><script>const cards=[...document.querySelectorAll('article')],ch=document.querySelector('#chapter'),pr=document.querySelector('#priority'),q=document.querySelector('#search');function filter(){let n=0;for(const c of cards){c.hidden=!!((ch.value&&c.dataset.ch!==ch.value)||(pr.value&&c.dataset.priority!==pr.value)||(q.value&&!c.innerText.toLocaleLowerCase().includes(q.value.toLocaleLowerCase())));if(!c.hidden)n++}document.querySelector('#count').textContent=n+' مورد'}[ch,pr,q].forEach(e=>e.addEventListener('input',filter));filter();</script></html>'''
(R/'review/Answer_Illustrations_Ch3-10_FA.html').write_text(body)
print(json.dumps({k:result[k]for k in ['questionsReviewed','recommendedQuestionUses','uniqueSuggestedFiles']},ensure_ascii=False))
if __name__=='__main__':pass
